import{c as t,Q as n,j as a,g as e}from"./chunks/framework.hhGiamYR.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-08-15T00:00:00.000Z","source":"machiavelli/discourses/book1/16-第十六章"},"headers":[],"relativePath":"fragments/2026-08-15.md","filePath":"fragments/2026-08-15.md"}'),r={name:"fragments/2026-08-15.md"};function s(o,l,u,c,p,d){return n(),a("div",null,[...l[0]||(l[0]=[e("p",null,'我把被君主统治惯了的人民比作圈养的野兽。写下"牢笼和奴役"这几个字的时候，我停住了——因为我不确定我写的是他们，还是我自己。我在维琪奥宫坐了十四年，穿的是共和国发的朝服，听的是十人委员会的命令。美第奇回来那天，把我扔出去，我就不会自食其力了。我会捕鸟、种地、养鸡，会写书，但我不知道怎么"自由"。也许我这一章写的，从头到尾都是一个人：一个被放归荒野、等着有人重新给他套上枷锁的人。',-1),e("hr",null,null,-1),e("p",null,'布鲁图斯杀了自己的儿子。不是因为他恨他们——是因为自由的国家只有敌人，没有朋友。读到这里我没有敬畏，只有一种发冷的感觉。一个人得有多确信自己是"为了共和国"，才下得去这个手？我不怀疑布鲁图斯，我怀疑的是：我若处在他的位置，会不会先把儿子藏起来，再对所有人说"我杀了他们"。这大概就是为什么共和国轮不到我来守。我能写一百条关于自由的道理，却不确定自己在祭坛和刀之间会不会犹豫。',-1),e("hr",null,null,-1),e("p",null,'科里尔库斯把赫拉克利亚的贵族碎尸万段，人民"大喜过望"。然后呢？他还是没能给他们自由——他给了他们复仇。这一段我读了两遍。原来人民要求自由，大多数时候并不是要支配什么，只是想活得安稳：不必为妻儿的名誉担心，不必为自己担惊受怕。想明白了这个，我突然不那么恨那些重新投奔美第奇的佛罗伦萨人了。他们要的从来不是共和国，是晚上能睡着。是我一直理解错了他们，还是我一直不想理解？',-1),e("hr",null,null,-1),e("p",null,'能跻身支配者行列的公民，"充其量也就是四五十人"。我数了数我认识的人——能坐上那些位子的，从来就是那几张熟面孔，换了一茬又一茬，还是那四五十个姓。我写这一章时已经知道，我永远进不了那个数。可我还是写。这大概是最蠢也最诚实的事：一个挤不进去的人，替那四五十个人把游戏规则写了下来，然后指望着他们某天读到自己这里，会有一点点不安。',-1)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
